g1 = primitives.call(name='ground_robocasa365_visual_target', entity_name='vegetable')
print('g1 ok', g1.ok)
out = g1.output
print(type(out))
if isinstance(out, dict):
    for k, v in out.items():
        s = str(v)
        print(k, s[:200])
else:
    print(str(out)[:800])

o = g1.output
try:
    eh = o['evidence_handle']
except Exception:
    eh = None
if eh is None:
    try:
        eh = o.get('evidence_handle')
    except Exception:
        pass
print('EH:', eh)
print('RAW:', str(o)[:400])
veg_eh = eh

def pick(o):
    v = None
    try:
        v = o['evidence_handle']
    except Exception:
        v = None
    if v is None:
        try:
            v = o['handle']
        except Exception:
            v = None
    if v is None:
        try:
            hs = o['evidence_handles']
            if isinstance(hs, list) and len(hs) > 0:
                v = hs[0]
        except Exception:
            v = None
    return v

lv = primitives.call(name='locate_robocasa365_object', object_name='vegetable')
lm = primitives.call(name='locate_robocasa365_object', object_name='meat')
veg_h = pick(lv.output) if lv.ok else None
meat_h = pick(lm.output) if lm.ok else None
print('lv', lv.ok, 'lm', lm.ok, 'veg', veg_h, 'meat', meat_h)

if veg_h is not None:
    g = primitives.call(name='grasp_robocasa365_object', object_name='vegetable',
                        evidence_handles=[veg_h], gripper_command=1.0, horizon=40,
                        grasp_approach='center', grasp_wrist_yaw_offset_rad=0.0)
    print('grasp veg', g.ok, str(g.output)[:200])

o = gv.output
print("START")
if isinstance(o, dict):
    for k in o:
        print(k, "=", str(o[k])[:150])
else:
    print("nondict", str(o)[:300])

obs = primitives.call(name='observe_robocasa365_rgbd', camera_name='robot0_eye_in_hand')
print("obsok", obs.ok)
oo = obs.output
if isinstance(oo, dict):
    print("K", list(oo.keys()))
    for k in oo:
        print(k, str(oo[k])[:200])
else:
    print("ND", str(oo)[:400])

