st = primitives.call(name='observe_robocasa365_kitchen_state')
objs = {}
try:
    d = st.output
    for k in ['vegetable','meat']:
        try:
            objs[k] = d['objects'][k]['position']
        except Exception:
            objs[k] = None
except Exception:
    pass
print('pos', str(objs)[:200])
p = objs.get('vegetable') or [4.24663, -0.35303, 0.96534]
gv2 = primitives.call(name='ground_robocasa365_visual_target', entity_name='vegetable', world_position=p)
print('gv2', gv2.ok)
if gv2.ok:
    vh = gv2.output['evidence_handle']
    print('vh', vh)
    g = primitives.call(name='grasp_robocasa365_object', object_name='vegetable',
                        evidence_handles=[vh], gripper_command=1.0, horizon=30,
                        grasp_approach='center', grasp_wrist_yaw_offset_rad=0.0)
    print('grasp', g.ok, str(g.output)[:300])
